/**
 * A Star for Christmas
 * 25 seconds, 3840 × 2160, 60 fps. The renderer supplies time in seconds.
 * Video encoder target: 100 Mbps.
 */
function draw(ctx, time, width, height) {
  const duration = 25;
  const t = ((time % duration) + duration) % duration;
  const tau = Math.PI * 2;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, minSide / 1080);
  const charcoal = "#252526";
  const ivory = "#F4EDE1";
  const gold = "#DFBF72";
  const taupe = "#A99B83";
  const stationCount = 48;
  const orbitTiming = [
    [0, 0, 0.33],
    [7, 1.37, 0.059],
    [16, 1.74, 0.061],
    [19.77, Math.PI, 0.58],
    [25, tau, 0.33]
  ];
  const transfers = [[6, 1081, 7.66, 10.72], [5, 960, 7.94, 11], [4, 839, 8.22, 11.28]];
  const ruleY = 695;

  function smooth(value) {
    const u = Math.max(0, Math.min(1, value));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function ease(start, end) {
    return smooth((t - start) / (end - start));
  }

  function envelope(inStart, inEnd, outStart, outEnd) {
    return ease(inStart, inEnd) * (1 - ease(outStart, outEnd));
  }

  // The orbit has matched angular velocity and acceleration at each key.
  function orbitAngle() {
    let i = 0;
    while (t >= orbitTiming[i + 1][0]) i++;
    const [start, angleA, speedA] = orbitTiming[i];
    const [end, angleB, speedB] = orbitTiming[i + 1];
    const span = end - start;
    const u = (t - start) / span;
    const u3 = u * u * u;
    const tangentA = u + u3 * (-6 + u * (8 - 3 * u));
    const tangentB = u3 * (-4 + u * (7 - 3 * u));
    return angleA + (angleB - angleA) * smooth(u) + span * (speedA * tangentA + speedB * tangentB);
  }

  function orbitPoint(angle) {
    return [960 - 622 * Math.cos(angle), 251 + 80 * Math.sin(angle) + 5 * Math.cos(2 * angle)];
  }

  function dot(x, y, radius) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, tau);
    ctx.fill();
  }

  function star(x, y) {
    const vertices = [];
    for (let i = 0; i < 16; i++) {
      const a = -Math.PI / 2 + i * tau / 16;
      const r = i % 2 === 1 ? 24 : i % 8 === 0 ? 74 : i % 4 === 0 ? 62 : 43;
      vertices.push([Math.cos(a) * r, Math.sin(a) * r]);
    }
    ctx.save();
    ctx.translate(x, y);
    ctx.fillStyle = gold;
    ctx.beginPath();
    ctx.moveTo(...vertices[0]);
    for (const p of vertices.slice(1)) ctx.lineTo(...p);
    ctx.closePath();
    ctx.fill();

    for (let i = 0; i < 16; i += 2) {
      ctx.fillStyle = i < 8 ? "#EFD89E" : "#C9A35D";
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(...vertices[i]);
      ctx.lineTo(...vertices[(i + 1) % 16]);
      ctx.closePath();
      ctx.fill();
    }

    ctx.strokeStyle = "#9F7F49";
    ctx.lineWidth = 1.35;
    ctx.beginPath();
    for (let i = 0; i < 16; i += 4) {
      const [px, py] = vertices[i];
      ctx.moveTo(px * 0.25, py * 0.25);
      ctx.lineTo(px * 0.84, py * 0.84);
    }
    ctx.stroke();

    ctx.fillStyle = "#F5E4B7";
    ctx.beginPath();
    ctx.moveTo(0, -10);
    ctx.lineTo(8, 0);
    ctx.lineTo(0, 10);
    ctx.lineTo(-8, 0);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  function cubic(a, b, c, d, u) {
    const v = 1 - u;
    return v * v * v * a + 3 * v * v * u * b + 3 * v * u * u * c + u * u * u * d;
  }

  function transferPoint(x, y, target, amount) {
    const junction = x + 34;
    const split = 0.62;
    if (amount <= split) {
      const u = amount / split;
      return [cubic(x, x - 9, x + 5, junction, u), cubic(y, y + 112, ruleY, ruleY, u)];
    }
    const u = (amount - split) / (1 - split);
    return [cubic(junction, junction + 29 * (1 - split) / split, target - 80, target, u), ruleY];
  }

  function heading(y, opacity) {
    if (opacity <= 0) return;
    const text = "Christmas";
    const family = 'Georgia, "Bitstream Charter", "Liberation Serif", serif';
    ctx.font = `400 163px ${family}`;
    let metrics = ctx.measureText(text);
    const fit = Math.min(1, 813 / (metrics.actualBoundingBoxLeft + metrics.actualBoundingBoxRight),
      118 / (metrics.actualBoundingBoxAscent + metrics.actualBoundingBoxDescent));
    if (fit < 1) {
      ctx.font = `400 ${163 * fit}px ${family}`;
      metrics = ctx.measureText(text);
    }
    ctx.fillStyle = ivory;
    ctx.globalAlpha = opacity;
    ctx.fillText(text, 960 + (metrics.actualBoundingBoxLeft - metrics.actualBoundingBoxRight) / 2,
      y + (metrics.actualBoundingBoxAscent - metrics.actualBoundingBoxDescent) / 2);
    ctx.globalAlpha = 1;
  }

  function label(y, opacity) {
    if (opacity <= 0) return;
    const text = "SHINE THIS";
    ctx.font = '700 33px "Liberation Sans", Arial, sans-serif';
    const tracking = 6.4;
    const widths = [...text].map(letter => ctx.measureText(letter).width);
    const total = widths.reduce((sum, w) => sum + w, 0) + tracking * (text.length - 1);
    let x = 960 - total / 2;
    ctx.fillStyle = gold;
    ctx.globalAlpha = opacity;
    for (let i = 0; i < text.length; i++) {
      ctx.fillText(text[i], x, y);
      x += widths[i] + tracking;
    }
    ctx.globalAlpha = 1;
  }

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.shadowColor = "transparent";
  ctx.filter = "none";
  ctx.fillStyle = charcoal;
  ctx.fillRect(0, 0, width, height);
  ctx.translate((width - 1920 * scale) / 2, (height - 1080 * scale) / 2);
  ctx.scale(scale, scale);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.setLineDash([]);
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  ctx.direction = "ltr";

  ctx.strokeStyle = "#615B50";
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(114, 116);
  ctx.lineTo(206, 116);
  ctx.moveTo(1714, 116);
  ctx.lineTo(1806, 116);
  ctx.stroke();

  // Scene 1, 0–7 s: the star travels in the upper field and wakes the trail behind it.
  const angle = orbitAngle();
  const [starX, starY] = orbitPoint(angle);
  function trailWeight(stationAngle, x, y) {
    const behind = (angle - stationAngle + tau) % tau;
    const distance = Math.hypot(x - starX, y - starY);
    return smooth((behind - 0.065) / 0.28) * (1 - smooth((behind - 0.95) / 1.06))
      * smooth((distance - 82) / 39);
  }

  for (let i = 0; i < stationCount; i++) {
    const stationAngle = i * tau / stationCount;
    const [x, y] = orbitPoint(stationAngle);
    const transfer = transfers.find(item => item[0] === i);
    if (transfer && t >= transfer[2] && t < 20.3) continue;
    ctx.globalAlpha = 0.82 * trailWeight(stationAngle, x, y);
    ctx.fillStyle = i % 2 === 0 ? gold : taupe;
    dot(x, y, i % 2 === 0 ? 4.3 : 3.1);
  }
  ctx.globalAlpha = 1;
  star(starX, starY);

  // Scene 2, 7–16 s: three dots take a separate lane and become the underline.
  const lineFade = 1 - ease(17.27, 19.18);
  for (const [index, target, start, end] of transfers) {
    if (t < start || lineFade <= 0) continue;
    const stationAngle = index * tau / stationCount;
    const [x, y] = orbitPoint(stationAngle);
    const amount = ease(start, end);
    const [px, py] = transferPoint(x, y, target, amount);
    const blend = smooth(amount / 0.2);
    ctx.fillStyle = index % 2 === 0 ? gold : taupe;
    ctx.globalAlpha = lineFade * (0.82 * trailWeight(stationAngle, x, y) * (1 - blend) + 0.88 * blend);
    dot(px, py, index % 2 === 0 ? 4.3 : 3.1);
  }
  const rule = ease(11.36, 12.89);
  ctx.globalAlpha = lineFade * rule;
  ctx.strokeStyle = gold;
  ctx.lineWidth = 1.9;
  ctx.beginPath();
  for (const x of [849, 970]) {
    ctx.moveTo(x, ruleY);
    ctx.lineTo(x + 101 * rule, ruleY);
  }
  ctx.stroke();
  ctx.globalAlpha = 1;

  // Scene 3, 16–25 s: the greeting clears while the star finishes the closed route.
  label(455 + 10 * (1 - ease(8.55, 10.37)), envelope(8.55, 10.37, 17.06, 18.94));
  heading(563 + 15 * (1 - ease(9.18, 11.15)) - 6 * ease(17.31, 19.38),
    envelope(9.18, 11.15, 17.31, 19.38));

  ctx.beginPath();
  ctx.restore();
}

/**
 * Home for Christmas
 * 25 seconds, 3840 × 2160, 60 fps. The renderer supplies time in seconds.
 * Video encoder target: 100 Mbps.
 */
function draw(ctx, time, width, height) {
  const duration = 25;
  const t = ((time % duration) + duration) % duration;
  const phase = 2 * Math.PI * t / duration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, minSide / 1080);
  const sky = "#D3E3ED";
  const ink = "#253F55";
  const slate = "#5E7F98";
  const amber = "#D59B53";
  const houses = [
    {
      x: 393, width: 210, wall: 126, roof: 72, ridge: 0, ridgeWidth: 0, chimney: 61,
      siding: "#9AB2C4", shingles: slate, doorX: 0, doorWidth: 46, doorHeight: 62,
      windows: [[-62, 30, 39, 42], [62, 30, 39, 42]]
    },
    {
      x: 916, width: 258, wall: 172, roof: 103, ridge: 0, ridgeWidth: 0, chimney: 78,
      siding: "#86A3B9", shingles: "#4E6E88", doorX: 0, doorWidth: 49, doorHeight: 73,
      windows: [[-68, 27, 45, 41], [68, 27, 45, 41], [-68, 89, 45, 41], [68, 89, 45, 41]],
      attic: true
    },
    {
      x: 1449, width: 286, wall: 136, roof: 77, ridge: -20, ridgeWidth: 89, chimney: 93,
      siding: "#A6BBCA", shingles: "#66849B", doorX: 46, doorWidth: 47, doorHeight: 65,
      windows: [[-93, 33, 39, 44], [-32, 33, 39, 44], [106, 33, 39, 44]]
    }
  ];

  function smooth(value) {
    const u = Math.max(0, Math.min(1, value));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function ease(start, end) {
    return smooth((t - start) / (end - start));
  }

  function envelope(inStart, inEnd, outStart, outEnd) {
    return ease(inStart, inEnd) * (1 - ease(outStart, outEnd));
  }

  function windowColor(amount) {
    const r = Math.round(69 + 144 * amount);
    const g = Math.round(96 + 59 * amount);
    const b = Math.round(117 - 34 * amount);
    return `rgb(${r}, ${g}, ${b})`;
  }

  function circle(x, y, r) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  function pane(x, y, w, h, warmth) {
    ctx.fillStyle = "#3E5A71";
    ctx.fillRect(x - w / 2, y, w, h);
    ctx.fillStyle = windowColor(warmth);
    ctx.fillRect(x - w / 2 + 4, y + 4, w - 8, h - 8);
    ctx.strokeStyle = "#3E5A71";
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(x, y + 4);
    ctx.lineTo(x, y + h - 4);
    ctx.moveTo(x - w / 2 + 4, y + h * 0.54);
    ctx.lineTo(x + w / 2 - 4, y + h * 0.54);
    ctx.stroke();
    ctx.fillStyle = "#D9E5E9";
    ctx.fillRect(x - w / 2 - 3, y + h + 3, w + 6, 3);
  }

  function door(x, w, h) {
    const left = x - w / 2;
    const right = x + w / 2;
    ctx.fillStyle = "#385770";
    ctx.beginPath();
    ctx.moveTo(left, 0);
    ctx.lineTo(left, -h + 11);
    ctx.quadraticCurveTo(left, -h, left + 11, -h);
    ctx.lineTo(right - 11, -h);
    ctx.quadraticCurveTo(right, -h, right, -h + 11);
    ctx.lineTo(right, 0);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = "#6E8A9E";
    ctx.lineWidth = 1.5;
    ctx.strokeRect(left + 8, -h + 14, w - 16, h - 24);
    ctx.fillStyle = amber;
    circle(right - 10.5, -h * 0.44, 2.65);
  }

  function house(shape, x, ground, heightShown, warmth, index) {
    if (heightShown <= 0) return;
    const half = shape.width / 2;
    const eave = -shape.wall;
    const crown = eave - shape.roof;
    const left = -half - 16;
    const right = half + 16;
    const ridgeLeft = shape.ridge - shape.ridgeWidth / 2;
    const ridgeRight = shape.ridge + shape.ridgeWidth / 2;
    const base = ground + shape.wall + shape.roof - heightShown;
    ctx.save();
    ctx.translate(x, base);

    const chimneyTop = eave - shape.roof * 0.76 - 13;
    const roofBelowChimney = shape.roof * (right - shape.chimney - 11.5) / (right - ridgeRight);
    ctx.globalAlpha = smooth((heightShown - shape.roof + roofBelowChimney - 3) / 21);
    ctx.fillStyle = "#4F7189";
    ctx.fillRect(shape.chimney - 11.5, chimneyTop, 23, eave - chimneyTop + 2);
    ctx.fillStyle = "#3D5F79";
    ctx.fillRect(shape.chimney - 15, chimneyTop - 5.5, 30, 7.5);
    ctx.globalAlpha = 1;

    ctx.fillStyle = shape.siding;
    ctx.fillRect(-half, eave, shape.width, shape.wall + 1);
    ctx.strokeStyle = "#6C8AA0";
    ctx.lineWidth = 1.7;
    ctx.strokeRect(-half, eave, shape.width, shape.wall + 1);

    ctx.fillStyle = shape.shingles;
    ctx.strokeStyle = "#476780";
    ctx.lineWidth = 1.7;
    ctx.beginPath();
    ctx.moveTo(left, eave);
    ctx.lineTo(ridgeLeft, crown);
    if (shape.ridgeWidth > 0) ctx.lineTo(ridgeRight, crown);
    ctx.lineTo(right, eave);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    const trim = 8 / shape.roof;
    ctx.strokeStyle = "#D9E6EC";
    ctx.lineWidth = 2.7;
    ctx.beginPath();
    ctx.moveTo(left + (ridgeLeft - left) * trim + 8, eave - 8);
    ctx.lineTo(right + (ridgeRight - right) * trim - 8, eave - 8);
    ctx.stroke();

    const lit = warmth * (0.973 + 0.027 * Math.sin(2 * phase + index * 1.23));
    if (shape.attic) {
      ctx.fillStyle = "#3E5A71";
      circle(0, eave - 44, 14);
      ctx.fillStyle = windowColor(lit * 0.9);
      circle(0, eave - 44, 10);
      ctx.strokeStyle = "#3E5A71";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(0, eave - 53);
      ctx.lineTo(0, eave - 35);
      ctx.stroke();
    }
    for (const [windowX, offset, w, h] of shape.windows) {
      pane(windowX, eave + offset, w, h, lit);
    }
    door(shape.doorX, shape.doorWidth, shape.doorHeight);
    ctx.restore();
  }

  function heading(x, y, opacity) {
    if (opacity <= 0) return;
    const text = "Home for Christmas";
    const family = 'Georgia, "Bitstream Charter", "Liberation Serif", serif';
    ctx.font = `400 121px ${family}`;
    let metrics = ctx.measureText(text);
    const fit = Math.min(1, 1170 / (metrics.actualBoundingBoxLeft + metrics.actualBoundingBoxRight),
      104 / (metrics.actualBoundingBoxAscent + metrics.actualBoundingBoxDescent));
    if (fit < 1) {
      ctx.font = `400 ${121 * fit}px ${family}`;
      metrics = ctx.measureText(text);
    }
    ctx.globalAlpha = opacity;
    ctx.fillStyle = ink;
    ctx.fillText(text, x + metrics.actualBoundingBoxLeft,
      y + (metrics.actualBoundingBoxAscent - metrics.actualBoundingBoxDescent) / 2);
    ctx.globalAlpha = 1;
  }

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.shadowColor = "transparent";
  ctx.filter = "none";
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, width, height);
  ctx.translate((width - 1920 * scale) / 2, (height - 1080 * scale) / 2);
  ctx.scale(scale, scale);
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.setLineDash([]);
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  ctx.direction = "ltr";

  ctx.strokeStyle = "#9BB4C6";
  ctx.lineWidth = 1.7;
  ctx.beginPath();
  ctx.moveTo(160, 159);
  ctx.lineTo(260, 159);
  ctx.moveTo(1684, 159);
  ctx.lineTo(1759, 159);
  ctx.stroke();
  ctx.fillStyle = "#B4834C";
  circle(276, 159, 2.8);

  // Scene 1, 0–7 s: the ground draws left to right and a first roof surfaces.
  const groundAmount = 0.24 + 0.76 * envelope(0.04, 6.03, 23.86, 24.97);
  const firstRoof = 24 + (houses[0].roof - 24) * envelope(0.06, 4.98, 22.96, 24.89);

  // Scene 2, 7–16 s: the village rises in order and its windows warm from left to right.
  const cottage = houses[0].wall * envelope(7.03, 9.75, 21.03, 23.25);
  const townhouse = (houses[1].wall + houses[1].roof) * envelope(7.75, 10.73, 21.38, 23.7);
  const lodge = (houses[2].wall + houses[2].roof) * envelope(8.52, 11.55, 21.71, 24);
  const leftWarm = envelope(9.28, 11.42, 19.47, 20.94);
  const centerWarm = envelope(10.29, 12.35, 19.95, 21.37);
  const rightWarm = envelope(11.33, 13.43, 20.38, 21.82);

  // Scene 3, 16–25 s: the village widens into a low strip while the greeting clears.
  const strip = envelope(16.02, 19.4, 22.08, 24.89);
  const ground = 902 + 25 * strip;
  const groundLeft = 128 - 10 * strip;
  const groundRight = groundLeft + (1664 + 20 * strip) * groundAmount;
  ctx.save();
  ctx.beginPath();
  ctx.rect(groundLeft, 0, groundRight - groundLeft, ground);
  ctx.clip();
  house(houses[0], houses[0].x - 52 * strip, ground, firstRoof + cottage, leftWarm, 0);
  house(houses[1], houses[1].x + 12 * strip, ground, townhouse, centerWarm, 1);
  house(houses[2], houses[2].x + 58 * strip, ground, lodge, rightWarm, 2);
  ctx.restore();

  ctx.strokeStyle = slate;
  ctx.lineWidth = 2.8;
  ctx.beginPath();
  ctx.moveTo(groundLeft, ground);
  ctx.lineTo(groundRight, ground);
  ctx.stroke();

  const tick = 293 + 40 * Math.sin(2 * phase + 0.45);
  ctx.strokeStyle = "#A3BCCD";
  ctx.lineWidth = 1.7;
  ctx.beginPath();
  ctx.moveTo(groundLeft + 1, ground + 23);
  ctx.lineTo(groundLeft + 85 + 12 * Math.cos(2 * phase + 0.45), ground + 23);
  ctx.stroke();
  ctx.fillStyle = amber;
  circle(tick, ground + 23, 3.3);

  const titleOpacity = envelope(9.06, 11.78, 16.7, 19.54);
  heading(163, 411 + 16 * (1 - ease(9.06, 11.78)) - 6 * ease(16.7, 19.54), titleOpacity);
  const rule = ease(10.52, 12.22);
  ctx.globalAlpha = rule * (1 - ease(16.52, 19.29));
  ctx.strokeStyle = slate;
  ctx.lineWidth = 2.1;
  ctx.beginPath();
  ctx.moveTo(165, 524);
  ctx.lineTo(165 + 151 * rule, 524);
  ctx.stroke();
  ctx.globalAlpha *= smooth((rule - 0.75) / 0.25);
  ctx.fillStyle = "#B4834C";
  circle(334, 524, 4.1);

  ctx.beginPath();
  ctx.restore();
}

/**
 * Christmas Pattern Press
 * 25 seconds, 3840 × 2160, 60 fps. The renderer supplies time in seconds.
 * Video encoder target: 100 Mbps.
 */
function draw(ctx, time, width, height) {
  const duration = 25;
  const t = ((time % duration) + duration) % duration;
  const phase = 2 * Math.PI * t / duration;
  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1920, minSide / 1080);
  const pistachio = "#E4E8BE";
  const ink = "#344324";
  const moss = "#778544";
  const clay = "#B96A48";
  const cream = "#F0ECCE";
  const greenPaper = "#D5DDAA";
  const warmPaper = "#EEE0BB";
  const pitch = 230;
  const firstColumn = 1406;
  const panelCenter = firstColumn + pitch;
  const rows = [283, 520, 757];
  const tiles = [
    [0, 0, "cane", cream, moss, 0, 0],
    [0, 1, "stocking", warmPaper, clay, 7.02, 9.22],
    [1, 0, "star", greenPaper, ink, 7.38, 9.58],
    [1, 1, "cane", cream, clay, 7.78, 9.98],
    [2, 0, "stocking", cream, moss, 8.16, 10.36],
    [2, 1, "star", greenPaper, moss, 8.55, 10.75]
  ];

  function smooth(value) {
    const u = Math.max(0, Math.min(1, value));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function ease(start, end) {
    return smooth((t - start) / (end - start));
  }

  function envelope(inStart, inEnd, outStart, outEnd) {
    return ease(inStart, inEnd) * (1 - ease(outStart, outEnd));
  }

  function diamond(x, y, radius) {
    ctx.beginPath();
    ctx.moveTo(x, y - radius);
    ctx.lineTo(x + radius, y);
    ctx.lineTo(x, y + radius);
    ctx.lineTo(x - radius, y);
    ctx.closePath();
    ctx.fill();
  }

  function roundedBox(left, top, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(left + r, top);
    ctx.lineTo(left + w - r, top);
    ctx.quadraticCurveTo(left + w, top, left + w, top + r);
    ctx.lineTo(left + w, top + h - r);
    ctx.quadraticCurveTo(left + w, top + h, left + w - r, top + h);
    ctx.lineTo(left + r, top + h);
    ctx.quadraticCurveTo(left, top + h, left, top + h - r);
    ctx.lineTo(left, top + r);
    ctx.quadraticCurveTo(left, top, left + r, top);
    ctx.closePath();
  }

  function canePath() {
    ctx.beginPath();
    ctx.moveTo(-36, 45);
    ctx.lineTo(-36, -22);
    ctx.arc(0, -22, 36, Math.PI, 2 * Math.PI);
    ctx.lineTo(36, -10);
    ctx.arc(25.5, -10, 10.5, 0, Math.PI);
    ctx.lineTo(15, -22);
    ctx.arc(0, -22, 15, 0, Math.PI, true);
    ctx.lineTo(-15, 45);
    ctx.arc(-25.5, 45, 10.5, 0, Math.PI);
    ctx.closePath();
  }

  function stockingPath() {
    ctx.beginPath();
    ctx.moveTo(-31, -49);
    ctx.quadraticCurveTo(-31, -54, -26, -54);
    ctx.lineTo(18, -54);
    ctx.quadraticCurveTo(24, -54, 24, -48);
    ctx.lineTo(20, -8);
