    [0.59, 15, 18, 18, -16, 4.2],
    [0.77, 11, 15, 16, -13, 3.6]
  ];

  function smooth(p) {
    const u = Math.max(0, Math.min(1, p));
    return u * u * u * (10 + u * (-15 + 6 * u));
  }

  function ease(start, end) {
    return smooth((t - start) / (end - start));
  }

  function visibility(inStart, inEnd, outStart, outEnd) {
    return ease(inStart, inEnd) * (1 - ease(outStart, outEnd));
  }

  function dot(x, y, radius, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, tau);
    ctx.fill();
  }

  function diamond(x, y, rx, ry, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x, y - ry);
    ctx.lineTo(x + rx, y);
    ctx.lineTo(x, y + ry);
    ctx.lineTo(x - rx, y);
    ctx.closePath();
    ctx.fill();
  }

  // The needle is a closed, tapered blade rooted in the stem.
  function addNeedle(x, y, dx, dy, halfWidth, growth) {
    if (growth <= 0) return;
    const length = Math.hypot(dx, dy);
    const normalX = (-dy / length) * halfWidth * growth;
    const normalY = (dx / length) * halfWidth * growth;
    const midX = x + dx * growth * 0.47;
    const midY = y + dy * growth * 0.47;
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(midX + normalX, midY + normalY, x + dx * growth, y + dy * growth);
    ctx.quadraticCurveTo(midX - normalX, midY - normalY, x, y);
    ctx.closePath();
  }

  function sprig(x, y, angle, side, amount, size) {
    if (amount <= 0) return;
    const cx = 23;
    const cy = 2;
    const tipX = 64;
    const tipY = 29;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.scale(size, side * size);

    for (const direction of [1, -1]) {
      ctx.fillStyle = direction === 1 ? sage : paleSage;
      ctx.beginPath();
      for (const [u, dxA, dyA, dxB, dyB, bladeWidth] of needlePairs) {
        const blade = smooth((amount - u) / 0.21);
        const rootX = 2 * (1 - u) * u * cx + u * u * tipX;
        const rootY = 2 * (1 - u) * u * cy + u * u * tipY;
        if (direction === 1) addNeedle(rootX, rootY, dxA, dyA, bladeWidth, blade);
        else addNeedle(rootX, rootY, dxB, dyB, bladeWidth, blade);
      }
      ctx.fill();
    }

    const a = 1 - amount;
    ctx.strokeStyle = sage;
    ctx.lineWidth = 2.6;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(cx * amount, cy * amount,
      2 * a * amount * cx + amount * amount * tipX,
      2 * a * amount * cy + amount * amount * tipY);
    ctx.stroke();
    ctx.restore();
  }

  function sideOfWreath(x, y, side, reach) {
    if (reach <= 0.075) return;
    ctx.strokeStyle = "#5C856E";
    ctx.lineWidth = 2.3;
    ctx.globalAlpha = smooth((reach - 0.075) / 0.12);
    ctx.beginPath();
    ctx.arc(x, y, stemRadius, baseAngle + side * 0.075, baseAngle + side * reach, side < 0);
    ctx.stroke();
    ctx.globalAlpha = 1;

    for (let i = 0; i < stations.length; i++) {
      const offset = stations[i];
      const angle = baseAngle + side * offset;
      const open = smooth((reach - offset) / Math.min(0.37, arcLimit - offset));
      sprig(x + stemRadius * Math.cos(angle), y + stemRadius * Math.sin(angle), angle, side, open, 1);
      if (open > 0.33) {
        const orbit = (i === 2 || i === 5) ? 0.05 * Math.sin(4 * cycle + i * 0.64) : 0;
        const bead = baseAngle + side * (offset + 0.06 + orbit);
        ctx.globalAlpha = smooth((open - 0.33) / 0.59);
        dot(x + 241 * Math.cos(bead), y + 241 * Math.sin(bead), i % 2 === 0 ? 4.7 : 3.4, brass);
        ctx.globalAlpha = 1;
      }
    }
    ctx.globalAlpha = 1;
  }

  function ring(x, y, amount) {
    if (amount <= 0) return;
    ctx.strokeStyle = brass;
    ctx.lineWidth = 1.8;
    ctx.globalAlpha = 0.76 * smooth(amount / 0.2);
    ctx.beginPath();
    const top = -Math.PI / 2;
    const arc = Math.PI * amount;
    ctx.arc(x, y, 216, top - arc, top + arc);
    ctx.stroke();
    ctx.globalAlpha = 1;
  }

  function lettering(text, x, y, nominalSize, style, maxWidth, maxHeight, opacity, offsetY) {
    if (opacity <= 0) return;
    const family = 'Georgia, "Bitstream Charter", "Liberation Serif", serif';
    ctx.font = `${style} ${nominalSize}px ${family}`;
    let metrics = ctx.measureText(text);
    const fit = Math.min(1,
      maxWidth / (metrics.actualBoundingBoxLeft + metrics.actualBoundingBoxRight),
      maxHeight / (metrics.actualBoundingBoxAscent + metrics.actualBoundingBoxDescent));
    if (fit < 1) {
      ctx.font = `${style} ${nominalSize * fit}px ${family}`;
      metrics = ctx.measureText(text);
    }
    ctx.fillStyle = cream;
    ctx.globalAlpha = opacity;
    ctx.fillText(text,
      x + (metrics.actualBoundingBoxLeft - metrics.actualBoundingBoxRight) / 2,
      y + (metrics.actualBoundingBoxAscent - metrics.actualBoundingBoxDescent) / 2 + offsetY);
    ctx.globalAlpha = 1;
  }

  function marginRules(amount) {
    ctx.globalAlpha = 0.46;
    ctx.strokeStyle = brass;
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(147, 145);
    ctx.lineTo(147 + 80 + 140 * amount, 145);
    ctx.moveTo(147, 935);
    ctx.lineTo(147 + 58 + 102 * amount, 935);
    ctx.stroke();
    diamond(128, 145, 4, 4, brass);
    diamond(128, 935, 4, 4, brass);
    ctx.globalAlpha = 1;
  }

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = "source-over";
  ctx.shadowColor = "transparent";
  ctx.filter = "none";
  ctx.fillStyle = green;
  ctx.fillRect(0, 0, width, height);
  ctx.translate((width - 1920 * scale) / 2, (height - 1080 * scale) / 2);
  ctx.scale(scale, scale);
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  ctx.direction = "ltr";
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.setLineDash([]);

  // Scene 3, 16–25 s: the seal moves right, then returns to the seed position.
  const slide = visibility(16, 19.35, 21.3, 24.7);
  const x = 1236 + 128 * slide;
  const y = 536;
  const seedOpen = visibility(0, 2.55, 23.15, 24.94);
  const seedSeat = visibility(1.48, 4.62, 22.94, 24.94);
  const seedY = y - 28 + (stemRadius + 28) * seedSeat;
  const idle = (1 - seedSeat) * Math.sin(4 * cycle);
  marginRules(seedOpen);

  // Scene 1, 0–7 s: a seed sprig settles where the mirrored stems begin.
  sprig(x, seedY + 2.6 * idle, baseAngle - 0.26 * (1 - seedSeat) + 0.04 * idle, 1,
    0.63 + 0.37 * seedOpen, 1 + 0.52 * (1 - seedSeat));
  diamond(x, seedY + 2.6 * idle, 5.4, 6.2, brass);
  const leftReach = arcLimit * visibility(3.45, 10.8, 19.9, 22.83);
  const rightReach = arcLimit * visibility(3.69, 11.02, 20.0, 22.92);
  sideOfWreath(x, y, 1, leftReach);
  sideOfWreath(x, y, -1, rightReach);

  // Scene 2, 7–16 s: the crown joins the two sides and the lettering settles inside.
  const crown = smooth((Math.min(leftReach, rightReach) - 2.55) / (arcLimit - 2.55));
  ctx.globalAlpha = crown;
  diamond(x, y - stemRadius, 10, 13, brass);
  dot(x - 17, y - stemRadius, 2.9, brass);
  dot(x + 17, y - stemRadius, 2.9, brass);
  ctx.globalAlpha = 1;
  ring(x, y, visibility(7.76, 10.72, 21.06, 22.68));

  const firstLine = visibility(9.04, 11.3, 20.52, 21.92);
  const secondLine = visibility(9.77, 12.1, 20.28, 21.77);
  lettering("Season’s", x, y - 39, 60, "400", 294, 57, firstLine, 12 * (1 - ease(9.04, 11.3)));
  lettering("Greetings", x, y + 40, 82, "italic 700", 328, 76, secondLine, 12 * (1 - ease(9.77, 12.1)));

  ctx.globalAlpha = visibility(10.86, 12.7, 20.22, 21.78);
  diamond(x, y - 118, 6.6, 8.6, brass);
  dot(x - 21, y - 118, 2.3, brass);
  dot(x + 21, y - 118, 2.3, brass);
  ctx.strokeStyle = brass;
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(x - 65, y + 122);
  ctx.lineTo(x - 15, y + 122);
  ctx.moveTo(x + 15, y + 122);
  ctx.lineTo(x + 65, y + 122);
  ctx.stroke();
  diamond(x, y + 122, 5.5, 5.5, brass);

  ctx.beginPath();
  ctx.restore();
}
